def mpl_dates_to_datestrings(dates, mpl_formatter):
    """Convert matplotlib dates to iso-formatted-like time strings.

    Plotly's accepted format: "YYYY-MM-DD HH:MM:SS" (e.g., 2001-01-01 00:00:00)

    Info on mpl dates: http://matplotlib.org/api/dates_api.html

    """
    _dates = dates

    # this is a pandas datetime formatter, times show up in floating point days
    # since the epoch (1970-01-01T00:00:00+00:00)
    if mpl_formatter == "TimeSeries_DateFormatter":
        try:
            dates = matplotlib.dates.epoch2num([date * 24 * 60 * 60 for date in dates])
            dates = matplotlib.dates.num2date(dates)
        except Exception:
            return _dates

    # the rest of mpl dates are in floating point days since
    # (0001-01-01T00:00:00+00:00) + 1. I.e., (0001-01-01T00:00:00+00:00) == 1.0
    # according to mpl --> try num2date(1)
    else:
        try:
            dates = matplotlib.dates.num2date(dates)
        except Exception:
            return _dates

    time_stings = [
        " ".join(date.isoformat().split("+")[0].split("T")) for date in dates
    ]
    return time_stings

def _export_color(color, opacity=None):
    """Export a matplotlib color for use as a plotly color.

    matplotlib uses "none" for fully transparent colors, which plotly does not
    accept, so transparent colors are exported as transparent black. Colors
    already exported by the mplexporter (hex or rgba strings) keep the alpha
    they carry unless an explicit opacity overrides it.
    """
    if color is None:
        return None
    if isinstance(color, (list, tuple)) and all(isinstance(c, str) for c in color):
        return [_export_color(c, opacity) for c in color]
    if not isinstance(color, str):
        color = export_color(color)
    if color == "none":
        return "rgba(0,0,0,0)"
    if color.startswith("#") and opacity is not None:
        return "rgba{0}".format(hex_to_rgb(color) + (opacity,))
    if color.startswith("rgb") and opacity not in (None, 1):
        rgb = color[color.index("(") + 1 : color.rindex(")")].split(",")
        r, g, b = (int(round(float(component))) for component in rgb[:3])
        return "rgba({0}, {1}, {2}, {3})".format(r, g, b, opacity)
    return color

